mapper.select:
SELECT t.id, t.mobile_no, t.partner_user_id, t.device_no, t.profile_id, t.agreement_type, t.agreed, t.agreed_at, t.clicked_at_ms FROM user_agreement_record t INNER JOIN ( SELECT agreement_type, MAX(id) AS max_id FROM user_agreement_record WHERE mobile_no = #{mobileNo}
AND agreement_type IN
#{type}
GROUP BY agreement_type ) latest ON t.id = latest.max_id ORDER BY t.agreement_type ASC
